CREATE TABLE IF NOT EXISTS meetings (id TEXT PRIMARY KEY, secret TEXT NOT NULL, title TEXT NOT NULL, schedule TEXT NOT NULL, phase TEXT NOT NULL DEFAULT 'collect', agenda TEXT NOT NULL DEFAULT '[]', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY, meeting TEXT NOT NULL REFERENCES meetings(id), label TEXT NOT NULL, detail TEXT NOT NULL, kind TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS votes (meeting TEXT NOT NULL REFERENCES meetings(id), voter TEXT NOT NULL, pick1 TEXT NOT NULL DEFAULT '', pick2 TEXT NOT NULL DEFAULT '', PRIMARY KEY(meeting,voter));
